def backfill_normalized_subjects(apps, schema_editor):
    AuditEvent = apps.get_model("audit", "AuditEvent")
    AuditEventSubject = apps.get_model("audit", "AuditEventSubject")
    Person = apps.get_model("people", "Person")
    unresolved = {"missing": 0, "malformed": 0, "dangling": 0, "ambiguous": 0}
    batch = []
    batch_size = 500

    def flush(items):
        if not items:
            return
        valid_ids = set(Person.objects.filter(pk__in={item[1] for item in items}).values_list("pk", flat=True))
        for event_id, person_id in items:
            if person_id not in valid_ids:
                unresolved["dangling"] += 1
                continue
            AuditEventSubject.objects.get_or_create(
                event_id=event_id,
                subject_type="PERSON",
                person_id=person_id,
            )

    for event in AuditEvent.objects.all().iterator(chunk_size=batch_size):
        person_id = None
        if isinstance(event.metadata, dict):
            person_id = event.metadata.get("person_id")
        if person_id is None and event.entity_type == "Person":
            person_id = event.entity_id
        if person_id is None:
            unresolved["missing"] += 1
            continue
        try:
            normalized_person_id = int(person_id)
            if normalized_person_id <= 0:
                raise ValueError
        except (TypeError, ValueError):
            unresolved["malformed"] += 1
            continue
        batch.append((event.pk, normalized_person_id))
        if len(batch) >= batch_size:
            flush(batch)
            batch = []
    flush(batch)
    logger.info("audit subject backfill completed unresolved_counts=%s", unresolved)


